CREATE TABLE [dbo].[ccSettings](	  [setting_id] TINYINT NOT NULL	, [valor] VARCHAR(300) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [descripcion] VARCHAR(80) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [Status] TINYINT NULL	, [Tipo] VARCHAR(3) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [detalle] VARCHAR(600) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [description] VARCHAR(600) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [bLoadSettings] BIT NOT NULL DEFAULT((0))	, [validate] VARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NULL DEFAULT('')	, CONSTRAINT [PK_ccSettings] PRIMARY KEY ([setting_id] ASC))